"""Bilingual isolated source chapter; explicit evidence and observation scopes."""
import datetime,hashlib,json,re
from pathlib import Path
P=Path(__file__).resolve().parent;pack=json.loads((P/'humanize-source-pack-v1.json').read_text());units=pack['units'];claims=[];C='v1.0.1:';O='v1.0.0:'
def add(id,section,en,pt,names,cases=()):
 assert re.findall(r'`([^`]+)`',en)==re.findall(r'`([^`]+)`',pt),id
 refs=[x if ':'in x else C+x for x in names];assert all(x in units for x in refs)
 claims.append({'id':id,'section':section,'en':en,'pt-br':pt,'evidence_ids':refs,'runtime_case_ids':list(cases),'review_status':'AGENT_SOURCE_REVIEWED_NOT_OWNER_GOLD'})
add('purpose','Purpose / Propósito','The pinned `humanize` package converts sizes to display strings and parses size strings. Fixed-width byte APIs, arbitrary-precision byte APIs and SI magnitude/unit parsing have distinct contracts. Similar names do not imply identical accepted units or precision.','O pacote `humanize` fixado converte tamanhos em textos de exibição e interpreta textos de tamanho. APIs de bytes de largura fixa, APIs de precisão arbitrária e interpretação de magnitude e unidade SI possuem contratos distintos. Nomes semelhantes não implicam unidades aceitas ou precisão idênticas.',['Bytes','ParseBytes','ParseBigBytes','ParseSI'])
add('architecture','Architecture / Arquitetura','`Bytes` and `IBytes` delegate to `humanateBytes`, using bases 1000 and 1024. `BigBytes` and `BigIBytes` delegate to `humanateBigBytes`, which copies its input before passing that copy to the mutating `oomm` helper. `ParseSI` follows a separate regular-expression and prefix-table path.','`Bytes` e `IBytes` delegam a `humanateBytes`, usando bases 1000 e 1024. `BigBytes` e `BigIBytes` delegam a `humanateBigBytes`, que copia sua entrada antes de passar essa cópia ao auxiliar mutável `oomm`. `ParseSI` segue um caminho separado de expressão regular e tabela de prefixos.',['Bytes','IBytes','humanateBytes','BigBytes','BigIBytes','humanateBigBytes','oomm','ParseSI'])
add('dependencies','Dependencies and configuration / Dependências e configuração','The selected root package imports only Go standard-library packages. The current module file declares `github.com/dustin/go-humanize` and `go 1.16`; the earlier selected tree has no root module file. This does not establish a tested minimum Go version. Observations used existing Go1.27.4 on Linux/ARM64, with CGO and package downloads disabled.','O pacote raiz selecionado importa apenas pacotes da biblioteca padrão Go. O arquivo de módulo atual declara `github.com/dustin/go-humanize` e `go 1.16`; a árvore anterior selecionada não possui arquivo de módulo na raiz. Isso não estabelece uma versão mínima de Go testada. As observações usaram o Go1.27.4 existente em Linux/ARM64, com CGO e downloads de pacotes desativados.',['ParseBytes','ParseBigBytes'])
add('formatting','Inputs and outputs / Entradas e saídas','Observed `Bytes(82854982)` returned `83 MB`; `IBytes(82854982)` returned `79 MiB`. The decimal and binary boundaries 1000 and 1024 returned `1.0 kB` and `1.0 KiB`. These are rounded display representations, not lossless serialization contracts.','O valor observado de `Bytes(82854982)` foi `83 MB`; `IBytes(82854982)` retornou `79 MiB`. Os limites decimal e binário 1000 e 1024 retornaram `1.0 kB` e `1.0 KiB`. São representações arredondadas para exibição, não contratos de serialização sem perdas.',['Bytes','IBytes','humanateBytes'],['format-decimal','format-binary','format-boundary','format-binary-boundary'])
add('parse-input','Inputs and outputs / Entradas e saídas','`ParseBytes` scans an initial digit/dot/comma prefix, removes its commas, calls `strconv.ParseFloat`, and lowercases and trims only the remaining unit text. Observations accepted `1,2,3 KB` as 123000, `1.5 KiB` as 1536 and `1.9 B` as 1. This is not strict grouping validation or a guarantee that every Unicode digit can be parsed.','`ParseBytes` percorre um prefixo inicial de dígitos, pontos e vírgulas, remove suas vírgulas, chama `strconv.ParseFloat` e converte para minúsculas e apara apenas o texto de unidade restante. As observações aceitaram `1,2,3 KB` como 123000, `1.5 KiB` como 1536 e `1.9 B` como 1. Isso não é validação estrita de agrupamento nem garantia de interpretação de todo dígito Unicode.',['ParseBytes'],['parse-loose-commas','parse-fraction-scale','parse-fraction-truncate','parse-unicode-digit'])
add('errors','Errors / Erros','The observed leading-space input ` 1 KB` and signed input `-1KB` failed numeric parsing. `1 QQ` failed unit lookup. `1e3` did not become exponent notation: the scanned number was followed by an unsupported unit. However, `1e` used the supported unit alias and produced 1000000000000000000.','A entrada observada com espaço inicial ` 1 KB` e a entrada com sinal `-1KB` falharam na interpretação numérica. `1 QQ` falhou na busca da unidade. `1e3` não virou notação exponencial: o número percorrido foi seguido de uma unidade não aceita. Porém, `1e` usou o alias de unidade aceito e produziu 1000000000000000000.',['ParseBytes'],['parse-leading-space','parse-negative','parse-unknown','parse-exponent','parse-e-unit'])
add('precision','Precision / Precisão','`ParseBytes` uses `float64`: the observed input `9007199254740993` returned `9007199254740992`, and `18446744073709551615` was rejected as too large. `ParseBigBytes` preserved the former integer exactly through its rational-number path. The arbitrary-precision API still truncated observed `1.9 B` to 1; arbitrary precision does not imply a fractional-byte result.','`ParseBytes` usa `float64`: a entrada observada `9007199254740993` retornou `9007199254740992`, e `18446744073709551615` foi rejeitada por ser grande demais. `ParseBigBytes` preservou exatamente o primeiro inteiro por seu caminho de número racional. A API de precisão arbitrária ainda truncou o valor observado `1.9 B` para 1; precisão arbitrária não implica resultado de bytes fracionários.',['ParseBytes','ParseBigBytes'],['parse-float-precision','parse-uint64-max','bigparse-exact-large','bigparse-fraction'])
add('units','Revision changes / Mudanças entre revisões','Between the pinned revisions, `ParseBigBytes` gained `RB`, `QB`, `RiB` and `QiB` aliases and their suffix-free forms. Observations accepted `1 QB` as 10^30 and `1 QiB` as 2^100 in the current cut; the earlier cut rejected them. This does not extend `ParseBytes`, which rejected `1 Rb` in both cuts. The two copies of the fixed-width parser source file are byte-identical.','Entre as revisões fixadas, `ParseBigBytes` ganhou aliases `RB`, `QB`, `RiB` e `QiB` e suas formas sem sufixo. As observações aceitaram `1 QB` como 10^30 e `1 QiB` como 2^100 no recorte atual; o anterior os rejeitou. Isso não amplia `ParseBytes`, que rejeitou `1 Rb` nos dois recortes. As duas cópias do arquivo de código do parser de largura fixa são idênticas em bytes.',['v1.0.0:ParseBigBytes','ParseBigBytes','ParseBytes'],['bigparse-quettabyte','bigparse-quebibyte','parse-new-big-unit'])
add('large-display','Revision changes / Mudanças entre revisões','For 10^30 bytes, observed `BigBytes` changed from `1000000 YB` to `1.0 QB`. For 2^100 bytes, `BigIBytes` changed from `1048576 YiB` to `1.0 QiB`. Both formatting paths preserved the supplied integer in these observations.','Para 10^30 bytes, o valor observado de `BigBytes` mudou de `1000000 YB` para `1.0 QB`. Para 2^100 bytes, `BigIBytes` mudou de `1048576 YiB` para `1.0 QiB`. Os dois caminhos de formatação preservaram o inteiro recebido nestas observações.',['v1.0.0:BigBytes','BigBytes','v1.0.0:BigIBytes','BigIBytes','humanateBigBytes','oomm'],['bigformat-quettabyte','bigformat-quebibyte'])
add('mutation','State and ownership / Estado e posse','`BigComma` has a different ownership contract: its loop divides the caller-supplied `big.Int` itself. Observed inputs 1234567 and -1234567 produced the expected signed grouped strings, but both input objects ended as 1. Pass an explicit copy when preservation is required; do not infer non-mutation from `BigBytes`.','`BigComma` possui outro contrato de posse: seu laço divide o próprio `big.Int` recebido do chamador. As entradas observadas 1234567 e -1234567 produziram os textos agrupados com sinal esperados, mas ambos os objetos de entrada terminaram como 1. Passe uma cópia explícita quando a preservação for necessária; não deduza ausência de mutação a partir de `BigBytes`.',['BigComma','oom','humanateBigBytes'],['bigcomma-positive','bigcomma-negative'])
add('si','SI parsing / Interpretação SI','Observed `ParseSI("1 QB")` changed from magnitude 1 with unit `QB` to magnitude 1e30 with unit `B`, because the prefix table acquired `Q`. Byte parsing and SI parsing therefore require separate statements about unknown suffixes. These observations do not verify every SI prefix, unit spelling or release.','O valor observado de `ParseSI("1 QB")` mudou de magnitude 1 com unidade `QB` para magnitude 1e30 com unidade `B`, pois a tabela de prefixos ganhou `Q`. Portanto, a interpretação de bytes e a interpretação SI exigem afirmações separadas sobre sufixos desconhecidos. Estas observações não verificam todo prefixo SI, escrita de unidade ou lançamento.',['v1.0.0:ParseSI','ParseSI','init','revfmap'],['parse-si-quetta'])
add('float-review','Limitations / Limitações','The 36 frozen cases ran once per revision. Exactly 35 predictions matched in each cut: `ComputeSI(1e-30)` rendered `1.0000000000000002` rather than the owned exact prediction `1`. The prefix changed from empty to `q` as predicted. The unmatched expectation is preserved as an owned prediction error, without an upstream-defect or broad numerical-accuracy claim.','Os 36 casos congelados foram executados uma vez por revisão. Exatamente 35 previsões coincidiram em cada recorte: `ComputeSI(1e-30)` exibiu `1.0000000000000002`, em vez da previsão própria exata `1`. O prefixo mudou de vazio para `q`, como previsto. A expectativa divergente está preservada como erro de previsão próprio, sem alegação de defeito no projeto externo ou de precisão numérica ampla.',['v1.0.0:ComputeSI','ComputeSI','logn'],['si-quecto'])
add('scope','Limitations / Limitações','The experiments compiled the complete selected non-test root package and executed its reviewed initializers and finite synthetic calls. They did not install packages, run upstream tests, contact application services or test Windows/macOS runtime behavior, concurrency, mutable-global tampering or arbitrary inputs. The module directive and license are source metadata, not compatibility or training-approval certificates.','Os experimentos compilaram o pacote raiz selecionado completo sem testes e executaram seus inicializadores revisados e chamadas sintéticas finitas. Não instalaram pacotes, executaram testes externos, contataram serviços de aplicação nem testaram execução em Windows/macOS, concorrência, adulteração de globais mutáveis ou entradas arbitrárias. A diretiva de módulo e a licença são metadados do código, não certificados de compatibilidade ou aprovação de treinamento.',['init','ParseBytes','ParseBigBytes','BigComma'])
faqspec=[('units','Do the new units also work in ParseBytes?','As novas unidades também funcionam em ParseBytes?','units'),('precision','Which parser preserved the integer above 2^53?','Qual parser preservou o inteiro acima de 2^53?','precision'),('commas','Does accepting commas prove strict thousands grouping?','Aceitar vírgulas comprova agrupamento estrito de milhares?','parse-input'),('mutation','Can the caller reuse a BigComma input unchanged?','O chamador pode reutilizar sem alterações uma entrada de BigComma?','mutation'),('si','Why document SI parsing separately?','Por que documentar a interpretação SI separadamente?','si'),('float','Did every exact numerical prediction match?','Todas as previsões numéricas exatas coincidiram?','float-review')]
byid={c['id']:c for c in claims};faq=[{'id':id,'en_q':en,'pt-br_q':pt,'en_a':byid[c]['en'],'pt-br_a':byid[c]['pt-br'],'claim_id':c,'evidence_ids':byid[c]['evidence_ids'],'runtime_case_ids':byid[c]['runtime_case_ids']}for id,en,pt,c in faqspec]
example='''package main

import (
    "fmt"
    "math/big"
    "github.com/dustin/go-humanize"
)

func main() {
    n := big.NewInt(1234567)
    copied := new(big.Int).Set(n)
    fmt.Println(humanize.BigComma(copied))
    _, err := humanize.ParseBigBytes("1 QB")
    if err != nil { panic(err) }
}'''
command='go doc github.com/dustin/go-humanize.ParseBigBytes'
diagram='''flowchart LR
    A[Bytes / IBytes] --> B[humanateBytes]
    C[BigBytes / BigIBytes] --> D[humanateBigBytes]
    D --> E[copy of input]
    E --> F[oomm]
    G[BigComma] --> H[divides caller input]'''
out=P/'humanize-chapter-candidates-v1';out.mkdir(exist_ok=False);files={}
for lang in ['en','pt-br']:
 lines=['# '+('Byte units, precision and input ownership'if lang=='en'else'Unidades de bytes, precisão e posse da entrada'),'','Research candidate; not published, owner-approved or training gold.'if lang=='en'else'Candidato de pesquisa; sem publicação, aprovação do proprietário ou gold de treinamento.','','Revisions: `9f541cc9db5d55bce703bd99987c9d5cb8eea45e` → `9ec74ab2f7a7161664182fd4e5e292fccffbc75f`.','']
 for section in dict.fromkeys(c['section']for c in claims):
  lines+=['## '+section.split(' / ')[0 if lang=='en'else 1],'']
  for c in claims:
   if c['section']==section:lines+=[c[lang]+' '+' '.join('[source:'+x+']'for x in c['evidence_ids'])+(' [runtime:'+','.join(c['runtime_case_ids'])+']'if c['runtime_case_ids']else''),'']
 lines+=['## '+('Illustrative example and command'if lang=='en'else'Exemplo e comando ilustrativos'),'','Example and command are illustrative and unexecuted; no output or installation success is claimed.'if lang=='en'else'Exemplo e comando são ilustrativos e não foram executados; nenhuma saída ou instalação bem-sucedida é afirmada.','','```go',example,'```','','```sh',command,'```','','[source:'+C+'BigComma] [source:'+C+'ParseBigBytes]','','## '+('API comparison'if lang=='en'else'Comparação de APIs'),'','| API | '+('Representation / ownership'if lang=='en'else'Representação / posse')+' |','|---|---|','| `ParseBytes` | `uint64`, `float64` |','| `ParseBigBytes` | `*big.Int`, `big.Rat` |','| `BigBytes` | '+('Copies input before helper'if lang=='en'else'Copia a entrada antes do auxiliar')+' |','| `BigComma` | '+('Mutates observed input'if lang=='en'else'Altera a entrada observada')+' |','','## '+('Written helper relationships'if lang=='en'else'Relações escritas entre auxiliares'),'','```mermaid',diagram,'```','','[source:'+C+'humanateBigBytes] [source:'+C+'BigComma]','','## FAQ','']
 for f in faq:lines+=['### '+f[lang+'_q'],'',f[lang+'_a']+' '+' '.join('[source:'+x+']'for x in f['evidence_ids']),'']
 lines+=['## '+('Physical evidence and license'if lang=='en'else'Evidência física e licença'),'','[Runtime receipt](../humanize-confined-runtime-results-v1.json); [prediction review](../humanize-runtime-prediction-review-v1.json).','']
 for id in sorted(set(x for c in claims for x in c['evidence_ids'])):
  u=units[id];url='https://github.com/dustin/go-humanize/blob/'+u['revision']+'/'+u['source_path']+'#L'+str(u['first_line'])+'-L'+str(u['last_line']);lines+=['- [source:'+id+'] ['+u['source_path']+':'+str(u['first_line'])+'–'+str(u['last_line'])+']('+url+'); SHA-256 `'+u['source_sha256']+'`.']
 for tag in ['v1.0.0','v1.0.1']:
  for name in ['LICENSE','go.mod']:
   entry=pack['sources'].get(tag+':'+name)
   if entry:lines+=['- '+tag+' ['+name+'](../'+entry['path']+'); SHA-256 `'+entry['sha256']+'`.']
 text='\n'.join(lines)+'\n';f=out/(lang+'.md')
 with f.open('x')as stream:stream.write(text)
 files[str(f.relative_to(P))]={'sha256':hashlib.sha256(text.encode()).hexdigest(),'bytes':len(text.encode())}
ledger={'at':datetime.datetime.now(datetime.timezone.utc).isoformat(),'repository':pack['repository'],'claims':claims,'faq':faq,'units':units,'files':files,'source_pack_sha256':hashlib.sha256((P/'humanize-source-pack-v1.json').read_bytes()).hexdigest(),'runtime_results_sha256':pack['runtime_results_sha256'],'owner_approved':False,'training_gold':False,'training_excluded':True,'publication_authorized':False,'example_executed':False,'command_executed':False,'source_initializers_and_selected_calls_executed':True,'faq_overlap':'All six FAQ answers reuse chapter claims; not six independent targets.','comparison_frozen_before_model_response':True}
with(P/'humanize-chapter-ledger-v1.json').open('x')as f:f.write(json.dumps(ledger,indent=2,ensure_ascii=False)+'\n')
print({'claims':len(claims),'faq_pairs':len(faq),'files':files})
